(3, NULL, 'تجهیزات پزشکی و توانبخشی', 'خرید تجهیزات حیاتی برای مراکز درمانی', 'توضیحات تکمیلی\r\n  تجهیزات پزشکی', NULL, 'food', 300000000, 170000000, NULL, '2026-05-26 12:47:54', '2026-06-07 09:17:16', 0, 3),
