(8, 'CAMP-20260524-6653', 'توسعه واکسن ضدسرطان', NULL, NULL, 'برای تحقیق و توسعه تولید واکسن ضد سرطان مکسا به حمایت ها و کمک های گرم شما نیازمند است. \r\nپیشاپیش از بذل عنایات شما کمال امتنان را داریم.', 'food', 50000000000, 801000000, '/uploads/campaigns/CAMP-20260524-6653/thumb.png', '2026-05-24 11:50:33', '2026-06-07 11:58:14', 1, 100),
(9, 'CAMP-20260524-6305', 'هیچکس تنها نیست', NULL, NULL, 'با ما در داستان مشارکت با همراه اول همراه باشید و مارا از حمایت های گرم خودتون بی نسیب نزارید. ', 'drug', 200000000, 220000000, '/uploads/campaigns/CAMP-20260524-6305/thumb.jpg', '2026-05-24 14:13:38', '2026-06-07 08:53:11', 1, 100),
(10, 'CAMP-20260524-9696', 'Make Iran Together ', NULL, NULL, 'با شرکت در این کمپین و حمایت های مالی بیایید در کنار هم ایرانی سالم تر و امن تر و شاد تر داشته باشیم.\r\nمکسا با ایران تا ابد', 'food', 4000000000, 0, '/uploads/campaigns/CAMP-20260524-9696/thumb.png', '2026-05-24 19:32:29', '2026-06-07 09:17:52', 1, 100),
(11, 'CAMP-20260525-4062', 'همه برای یکی، یکی برای همه', NULL, NULL, 'خیلی مختصر و مفید تمام اهداف کمپین در عنوان آن خلاصه شده اند.', 'education', 10000000, 0, '/uploads/campaigns/CAMP-20260525-4062/thumb.png', '2026-05-25 04:27:45', '2026-06-07 08:53:22', 1, 100),
(12, 'CAMP-20260607-2348', 'تا وقتی فنی هست چرا علوم پزشکی', NULL, NULL, 'در این طرح تلاش مکسا بر این گمارده شده که با به کار گیری دانش فنی دانشجویان در انشگاه های برتر و هم کاری آنان با دانشجویان رشته های پزشکی تغییرات شگرف و ستودنی در ایران عزیزمان ایجاد کنیم. \r\nاز کمک های بی پایان شما ملت نستوه و بردبار کمال امتنان را داریم.', 'education', 199999999, 0, '/uploads/campaigns/CAMP-20260607-2348/thumb.png', '2026-06-07 09:16:51', '2026-06-07 09:16:51', 1, 100);

