-- پایان مهاجرت 001
-- ============================================================================


-- ============================================================================
--  Migration 002 — سامانه‌ی تیکتینگ (Ticketing)  [بدون FOREIGN KEY برای سازگاری با هاست]
--  یکپارچگیِ داده در لایه‌ی برنامه (PHP) تضمین می‌شود. جزئیات: database/migrations/002_ticketing.sql
-- ============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `tickets` (
  `id`             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `branch_id`      INT UNSIGNED NOT NULL,
  `subject`        VARCHAR(200) NOT NULL,
  `target`         ENUM('branch','hq') NOT NULL,
  `priority`       ENUM('low','normal','high') NOT NULL DEFAULT 'normal',
  `status`         ENUM('open','answered','closed') NOT NULL DEFAULT 'open',
  `created_by`     INT UNSIGNED NOT NULL,
  `creator_role`   ENUM('user','branch_admin','super') NOT NULL,
  `escalated_from` INT UNSIGNED DEFAULT NULL,
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_reply_at`  DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tickets_branch`  (`branch_id`),
  KEY `idx_tickets_target`  (`target`),
  KEY `idx_tickets_creator` (`created_by`),
  KEY `idx_tickets_status`  (`status`),
  KEY `idx_tickets_escal`   (`escalated_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ticket_messages` (
  `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `ticket_id`   INT UNSIGNED NOT NULL,
  `user_id`     INT UNSIGNED NOT NULL,
  `author_role` ENUM('user','branch_admin','super') NOT NULL,
  `body`        TEXT NOT NULL,
  `created_at`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tmsg_ticket` (`ticket_id`),
  KEY `idx_tmsg_user`   (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ticket_reads` (
  `ticket_id`    INT UNSIGNED NOT NULL,
  `user_id`      INT UNSIGNED NOT NULL,
  `last_read_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ticket_id`, `user_id`),
  KEY `idx_tread_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ============================================================================
-- پایان مهاجرت 002
-- ============================================================================

-- فیلدهای موبایلی موردنیاز حساب بیمار
ALTER TABLE `panel_users`
  MODIFY COLUMN `email` VARCHAR(255) NULL,
  MODIFY COLUMN `password_hash` VARCHAR(255) NULL,
  ADD COLUMN IF NOT EXISTS `phone` VARCHAR(20) NULL AFTER `id`,
  ADD COLUMN IF NOT EXISTS `phone_verified_at` DATETIME NULL AFTER `email_verified_at`;
ALTER TABLE `panel_users` ADD UNIQUE INDEX IF NOT EXISTS `uq_panel_users_phone` (`phone`);

ALTER TABLE `user_profiles`
  ADD COLUMN IF NOT EXISTS `national_code` VARCHAR(10) NULL AFTER `last_name`;

CREATE TABLE IF NOT EXISTS `otp_codes` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `phone` VARCHAR(20) NOT NULL,
  `code_hash` VARCHAR(255) NOT NULL,
  `purpose` ENUM('donation_auth','login') NOT NULL DEFAULT 'donation_auth',
  `ip_address` VARCHAR(45) NOT NULL,
  `attempts` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `expires_at` DATETIME NOT NULL,
  `consumed_at` DATETIME NULL DEFAULT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_otp_phone_purpose_expires` (`phone`, `purpose`, `expires_at`),
  KEY `idx_otp_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `medical_records` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `branch_id` INT UNSIGNED NOT NULL,
  `full_name` VARCHAR(200) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `age` TINYINT UNSIGNED NULL,
  `gender` ENUM('male','female','unspecified') NOT NULL DEFAULT 'unspecified',
  `province` VARCHAR(100) NOT NULL,
  `city` VARCHAR(100) NOT NULL,
  `cancer_type` VARCHAR(100) NULL,
  `diagnosis_status` VARCHAR(100) NULL,
  `description` TEXT NULL,
  `status` ENUM('new','reviewing','contacted','closed') NOT NULL DEFAULT 'new',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_medical_records_user` (`user_id`),
  KEY `idx_medical_records_branch_status` (`branch_id`, `status`),
  CONSTRAINT `fk_medical_records_user` FOREIGN KEY (`user_id`) REFERENCES `panel_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_medical_records_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `medical_record_files` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `record_id` BIGINT UNSIGNED NOT NULL,
  `path` VARCHAR(500) NOT NULL,
  `original_name` VARCHAR(255) NOT NULL,
  `mime_type` VARCHAR(100) NOT NULL,
  `size` INT UNSIGNED NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_medical_record_files_record` (`record_id`),
  CONSTRAINT `fk_medical_record_files_record` FOREIGN KEY (`record_id`) REFERENCES `medical_records` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
